      {/* Chest Opening Experience Modal */}
      {showLootChestOpening && (
        <LandingDojoProvider>
          <ChestOpeningExperience
            onClose={handleCloseChestExperience}
            initialChestId={openingChest?.id}
            initialEpoch={openingChest?.epoch}
          />
        </LandingDojoProvider>
      )}
    </>
  );
};

